/**
 * Die Vortragsansicht.
 *
 * Die Folie füllt den Bildschirm, bei jedem Wechsel läuft der Übergang, und
 * Elemente mit einem `reveal`-Schritt über null kommen einzeln dazu. Die
 * Bedienknöpfe blenden sich aus, bis der Zeiger sich rührt.
 *
 * Das ist der einzige Bildschirm, den nicht der Benutzer sieht, sondern sein
 * Publikum. Er war deshalb auch der letzte, der noch englisch war — der
 * Sprachtest sah die Zeichenketten nicht, weil sie in Ausdrücken standen.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { canvas, motion } from '@/theme';
import { maxRevealStep, slideTitle } from '@/model/types';
import { selectCurrentSlide, useDeckStore } from '@/state/deckStore';
import { SlideView } from '@/components/canvas/SlideView';
import { IconButton, cx } from '@/components/ui/controls';
import { useElementSize } from '@/hooks/useElementSize';
import { usePresenterChannel } from '@/hooks/usePresenterChannel';
import { useFolienformatVersion } from '@/hooks/useFolienformat';

export function PresentView() {
  /*
     Das Folienmaß wird im Rumpf gelesen, das Format aber in einem Effekt
     gesetzt — und Effekte laufen *nach* dem Zeichnen. Ohne diesen Zähler
     bliebe nach dem Laden eines A4-Decks das 16:9-Blatt stehen, bis
     irgendetwas anderes ein Neuzeichnen auslöste. Derselbe Griff wie bei
     `useThemeVersion()`, und aus genau demselben Grund.
  */
  useFolienformatVersion();
  const deck = useDeckStore((state) => state.deck);
  const slide = useDeckStore(selectCurrentSlide);
  const slideIndex = useDeckStore((state) => state.slideIndex);
  const revealStep = useDeckStore((state) => state.revealStep);
  const notesOpen = useDeckStore((state) => state.notesOpen);

  const advance = useDeckStore((state) => state.advance);
  const retreat = useDeckStore((state) => state.retreat);
  const setMode = useDeckStore((state) => state.setMode);
  const toggleNotes = useDeckStore((state) => state.toggleNotes);

  const [setViewport, viewport] = useElementSize<HTMLDivElement>();
  const referent = usePresenterChannel();
  const [chromeVisible, setChromeVisible] = useState(true);
  const hideTimer = useRef<number | undefined>(undefined);

  const showChrome = useCallback(() => {
    setChromeVisible(true);
    window.clearTimeout(hideTimer.current);
    hideTimer.current = window.setTimeout(() => setChromeVisible(false), 2200);
  }, []);

  useEffect(() => {
    showChrome();
    return () => window.clearTimeout(hideTimer.current);
  }, [showChrome]);

  const scale =
    viewport.width > 0 && viewport.height > 0
      ? Math.min(viewport.width / canvas.width, viewport.height / canvas.height)
      : 0;

  if (!slide) return null;

  const steps = maxRevealStep(slide);
  const transitionClass = `nz-transition-${slide.meta.transition}`;

  return (
    <div
      ref={setViewport}
      className="relative flex h-full w-full items-center justify-center overflow-hidden bg-ui-inverse"
      onPointerMove={showChrome}
      onClick={(event) => {
        // Ein Klick auf die Folie blättert weiter, einer auf einen Knopf nicht.
        if ((event.target as HTMLElement).closest('button')) return;
        advance();
      }}
    >
      <div
        // Ein neuer Schlüssel je Folie startet den Übergang von vorn.
        key={`${slide.id}-${slideIndex}`}
        className={cx('nz-stage nz-stage--present overflow-hidden', transitionClass)}
        style={{
          width: canvas.width * scale,
          height: canvas.height * scale,
          animationDuration: `${motion.duration.slide}ms`,
        }}
      >
        <SlideView
          slide={slide}
          deck={deck}
          slideNumber={slideIndex + 1}
          totalSlides={deck.slides.length}
          revealStep={revealStep}
          animateReveals
          className="h-full w-full"
        />
      </div>

      {/* ---------------------------------------------------------- controls */}
      <div
        className={cx(
          'pointer-events-none absolute inset-x-0 bottom-0 flex items-end justify-between p-4',
          'transition-opacity duration-base ease-standard',
          chromeVisible ? 'opacity-100' : 'opacity-0',
        )}
      >
        <div className="pointer-events-auto flex items-center gap-1 rounded-md bg-ui-surface/95 px-2 py-1 shadow-ui-xl">
          <IconButton icon="arrow-left" label="Zurück" onClick={retreat} />
          <span className="min-w-16 text-center tabular-nums text-[12px] text-ui-muted">
            {slideIndex + 1} / {deck.slides.length}
            {steps > 0 ? ` · ${Math.min(revealStep, steps)}/${steps}` : ''}
          </span>
          <IconButton icon="arrow-right" label="Weiter" onClick={advance} />
        </div>

        <div className="pointer-events-auto flex items-center gap-1 rounded-md bg-ui-surface/95 px-2 py-1 shadow-ui-xl">
          <IconButton
            icon="list-check"
            label="Notizen für den Vortrag (N)"
            active={notesOpen}
            onClick={() => toggleNotes()}
          />
          <IconButton
            icon="table"
            label="Übersicht (⌘K)"
            onClick={() => useDeckStore.getState().toggleOverview(true)}
          />
          <IconButton
            icon="chalkboard"
            label="Referentenansicht öffnen"
            active={referent.offen}
            onClick={referent.oeffnen}
          />
          <IconButton
            icon="xmark"
            label="Präsentation verlassen (Esc)"
            onClick={() => setMode('edit')}
          />
        </div>
      </div>

      {/* ------------------------------------------------------------- notes */}
      {notesOpen ? (
        <aside className="pointer-events-auto absolute right-4 top-4 w-80 rounded-lg bg-ui-surface p-3 shadow-ui-xl">
          <h3 className="mb-1 text-ui-label font-bold uppercase tracking-wide text-ui-faint">
            Notizen · {slideTitle(slide, slideIndex)}
          </h3>
          <p className="whitespace-pre-wrap text-ui-body text-ui-muted">
            {slide.meta.notes?.trim() || 'Für diese Folie ist nichts notiert.'}
          </p>
        </aside>
      ) : null}

      <div
        className={cx(
          'pointer-events-none absolute inset-x-0 top-0 flex justify-center p-3',
          'transition-opacity duration-base ease-standard',
          chromeVisible ? 'opacity-70' : 'opacity-0',
        )}
      >
        <p className="rounded-pill bg-ui-surface/90 px-3 py-1 text-[11px] text-ui-muted">
          → / Leertaste weiter · ← zurück · F Vollbild · Esc verlassen
        </p>
      </div>
    </div>
  );
}
